CREATE TABLE "SocialPost" ("id" TEXT NOT NULL PRIMARY KEY,"title" TEXT NOT NULL,"caption" TEXT NOT NULL DEFAULT '',"mediaType" TEXT NOT NULL DEFAULT 'image',"mediaJson" TEXT NOT NULL DEFAULT '[]',"platformsJson" TEXT NOT NULL DEFAULT '[]',"status" TEXT NOT NULL DEFAULT 'draft',"scheduledAt" DATETIME,"approvedAt" DATETIME,"facebookStatus" TEXT NOT NULL DEFAULT 'pending',"instagramStatus" TEXT NOT NULL DEFAULT 'pending',"facebookPostId" TEXT,"instagramPostId" TEXT,"lastError" TEXT NOT NULL DEFAULT '',"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL);
CREATE INDEX "SocialPost_status_scheduledAt_idx" ON "SocialPost"("status","scheduledAt");
